 ) SELECT CAST(c.ordinal AS BIGINT),CAST(c.body->>'role' AS TEXT),CAST((c.body->>'task_id')::bigint AS BIGINT),CAST(c.body->>'product_key' AS TEXT),CAST(c.body->>'content_digest' AS TEXT),CAST(p_project AS TEXT),CAST(p_run AS BIGINT),CAST(p_release AS TEXT),CAST(p_task AS BIGINT),CAST(p_product AS TEXT),CAST(p_digest AS TEXT),CAST('pdf-companion-projection-v1:e5ade48a25e5bc6d89259d5e8ce5141926ccd8223bc3e173e19b808aacfea9f5'::text AS TEXT) FROM companions c  WHERE c.family='input';
END

