 SELECT count(*),COALESCE(sum((1+CASE WHEN s.product_id IS NULL THEN 0 ELSE 4+octet_length(s.product_id) END+CASE WHEN s.revision_id IS NULL THEN 0 ELSE 4+octet_length(s.revision_id) END+CASE WHEN s.release_id IS NULL THEN 0 ELSE 4+octet_length(s.release_id) END+CASE WHEN s.source_digest IS NULL THEN 0 ELSE 4+octet_length(s.source_digest) END+CASE WHEN s.mapping_profile IS NULL THEN 0 ELSE 4+octet_length(s.mapping_profile) END+CASE WHEN s.contract_version IS NULL THEN 0 ELSE 4+octet_length(s.contract_version) END+CASE WHEN s.native_schema_digest IS NULL THEN 0 ELSE 4+octet_length(s.native_schema_digest) END+CASE WHEN s.root_id IS NULL THEN 0 ELSE 4+octet_length(s.root_id) END)),0) INTO n,bytes FROM pg_temp.ps_pdf_stage_document s;
 total:=total+n; total_bytes:=total_bytes+bytes;
 IF total>65536 OR total_bytes>8388608 THEN RAISE EXCEPTION
